"""Daily sessions: generated once per study day, persisted in SQLite, never regenerated by a
refresh. Missed days are recorded without piling up work; the student decides what to do about
them BEFORE today's set is built (catch up on key revision inside today's set, resume the missed
set, or skip). The session timer measures active time only."""
from __future__ import annotations

from datetime import date, datetime, timedelta

from sqlalchemy import select
from sqlalchemy.orm import Session

from app.models import Attempt, DailySession, LearningPlanItem, Mastery, QuestionExposure, RevisionQueue, SessionQuestion
from app.models.common import utcnow
from app.selection.context import build_context
from app.selection.engine import budget_bounds, build_daily_selection, explain, subject_code
from app.services import clock, question_bank
from app.services import settings as st

ACTIVE = ("generated", "in_progress")
ANSWERED = ("submitted", "skipped")
NOTICE_DAYS = 7  # missed days older than this are no longer offered for a decision
HEARTBEAT_CREDIT = 90  # at most this many seconds are credited between two activity signals


def study_day(db: Session, d: date) -> bool:
    return d.weekday() in (st.get(db, "weekdays") or [0, 1, 2, 3, 4])


def get_session(db: Session, d: date) -> DailySession | None:
    return db.execute(select(DailySession).where(DailySession.session_date == d)).scalar_one_or_none()


def _answered(sess: DailySession) -> int:
    return sum(1 for q in sess.questions if q.status in ANSWERED)


def _planned_on(sess: DailySession) -> date | None:
    """The real day a session's set was planned, when that differs from its own date (a resumed
    missed day)."""
    expl = sess.explanation if isinstance(sess.explanation, dict) else {}
    v = expl.get("resumed_on") or expl.get("planned_on")
    try:
        return date.fromisoformat(v) if v else None
    except ValueError:
        return None


# ------------------------------------------------------------- missed days ---
def setup_floor(db: Session, today: date) -> date:
    """Missed days are counted only from the later of the Year 12 start and the day the app was
    first used to plan a session (no phantom missed days before installation)."""
    on = st.get(db, "setup_completed_on")
    if not on:
        first = db.execute(select(DailySession.session_date).where(DailySession.session_number > 0)
                           .order_by(DailySession.session_date).limit(1)).scalar_one_or_none()
        on = (first or today).isoformat()
        st.set_(db, "setup_completed_on", on)
    floor = date.fromisoformat(on)
    start_s = st.get(db, "year12_start_date")
    if start_s:
        floor = max(floor, date.fromisoformat(start_s))
    return floor


def record_missed(db: Session, today: date, lookback_days: int = 14) -> list[DailySession]:
    """Create 'missed' records for past study days with no session (no questions attached, so
    nothing accumulates). An earlier session that was never started becomes 'missed' too."""
    weekdays = st.get(db, "weekdays") or [0, 1, 2, 3, 4]
    floor = max(setup_floor(db, today), today - timedelta(days=lookback_days))
    created = []
    for d in clock.weekdays_between(floor - timedelta(days=1), today, weekdays):
        if get_session(db, d) is None:
            s = DailySession(session_date=d, status="missed", target_minutes=0, session_number=0)
            db.add(s)
            created.append(s)
    for s in db.execute(select(DailySession).where(DailySession.session_date < today, DailySession.status.in_(ACTIVE))).scalars():
        planned_on = _planned_on(s)
        if planned_on is not None and planned_on >= today:
            continue  # a missed day resumed today: it stays open (and keeps its questions out of today's set)
        if _answered(s) == 0:
            # an untouched resumed day is not offered again: the student already had that choice
            s.status = "skipped" if planned_on is not None else "missed"
        if s.timer_started_at is not None:
            pause_timer(db, s, "day_end")
    db.flush()
    if created:
        renumber(db)
    return created


def pending_missed(db: Session, today: date) -> list[DailySession]:
    return list(db.execute(select(DailySession).where(
        DailySession.status == "missed", DailySession.session_date < today,
        DailySession.session_date >= today - timedelta(days=NOTICE_DAYS),
    ).order_by(DailySession.session_date)).scalars())


def catch_up_candidates(db: Session, today: date, first_missed: date | None = None, k: int = 3) -> dict[int, dict]:
    """The 1–3 most important revision items around the missed day(s): weak-skill revision first."""
    rows = db.execute(select(RevisionQueue).where(RevisionQueue.status == "open", RevisionQueue.plan_item_id.is_not(None),
                                                  RevisionQueue.due_date <= today + timedelta(days=3))).scalars().all()
    mastery = {m.plan_item_id: m.mastery for m in db.execute(select(Mastery)).scalars()}
    best: dict[int, RevisionQueue] = {}
    for r in rows:
        if r.plan_item_id not in best or r.due_date < best[r.plan_item_id].due_date:
            best[r.plan_item_id] = r
    ranked = sorted(best.values(), key=lambda r: (-r.priority, mastery.get(r.plan_item_id, 0.5), r.due_date))
    out = {r.plan_item_id: {"priority": r.priority, "due": r.due_date, "reason": r.reason} for r in ranked[:k]}
    if not out:  # nothing scheduled: the weakest skills
        weak = sorted(((m.mastery, m.plan_item_id) for m in db.execute(select(Mastery).where(Mastery.attempts >= 3)).scalars() if m.mastery < 0.6))
        out = {i: {"priority": 0.8, "due": first_missed or today, "reason": "Weak skill"} for _m, i in weak[:2]}
    return out


def missed_notice(db: Session, today: date) -> dict | None:
    """One calm notice for all recent missed days (selection-11)."""
    pend = pending_missed(db, today)
    if not pend:
        return None
    days = [s.session_date for s in pend]
    labels = ", ".join(f"{d:%a %d %b}" for d in days)
    n = len(days)
    today_sess = get_session(db, today)
    items = catch_up_candidates(db, today, days[0])
    names = []
    for item_id in items:
        it = db.get(LearningPlanItem, item_id)
        if it is not None:
            names.append(f"{it.code} {it.title}" if it.chapter else it.title)
    return {
        "ids": [s.id for s in pend], "days": days, "latest_id": pend[-1].id,
        "text": f"You missed {n} session{'s' if n != 1 else ''} ({labels}). Nothing has piled up.",
        "catch_up_names": names, "today_started": bool(today_sess and _answered(today_sess)),
    }


def resolve_missed(db: Session, today: date, action: str, sid: int | None = None) -> DailySession | None:
    """Apply the student's choice to every pending missed day. Returns the session to open."""
    pend = pending_missed(db, today)
    if action == "resume":
        target = db.get(DailySession, sid) if sid else (pend[-1] if pend else None)
        if target is None:
            return None
        for s in pend:
            if s.id != target.id:
                s.status = "skipped"
        return resume_missed(db, target)
    if action == "catch_up":
        items = catch_up_candidates(db, today, pend[0].session_date if pend else None)
        for s in pend:
            s.status = "skipped"
            s.summary = {"resolution": "catch_up", "items": sorted(items)}
        return apply_catch_up(db, today, items)
    for s in pend:
        s.status = "skipped"
    db.flush()
    return None


def apply_catch_up(db: Session, today: date, items: dict[int, dict]) -> DailySession | None:
    """Fold the catch-up items into TODAY's set (replacing lower-priority slots, never adding).
    Idempotent: due dates move to today at most once and priorities are not bumped."""
    for r in db.execute(select(RevisionQueue).where(RevisionQueue.status == "open", RevisionQueue.plan_item_id.in_(list(items) or [-1]))).scalars():
        if r.due_date > today:
            r.due_date = today
    db.flush()
    sess = get_session(db, today)
    if sess is None:
        return generate(db, today, None, catch_up=items) if study_day(db, today) else None
    if _answered(sess) == 0 and sess.questions:
        return rebuild(db, sess, sess.mode, catch_up=items)
    return sess  # already under way: the revision items are due now and lead tomorrow's set


# ----------------------------------------------------------- generation ---
def _top_up_templates(db: Session) -> None:
    enrich = st.get(db, "enrichment_enabled")
    for item in db.execute(select(LearningPlanItem).where(LearningPlanItem.status != "LOCKED", LearningPlanItem.active.is_(True))).scalars():
        if item.subject.code == "MATHS" and (not item.enrichment or enrich):
            question_bank.ensure_template_questions(db, item)


def next_session_number(db: Session) -> int:
    return len(_numbered(db)) + 1


def _numbered(db: Session) -> list[DailySession]:
    return [s for s in db.execute(select(DailySession).order_by(DailySession.session_date)).scalars() if s.questions]


def renumber(db: Session) -> None:
    """'Session N' is the Nth study day with a set of questions, in date order (selection-14)."""
    n = 0
    for s in db.execute(select(DailySession).order_by(DailySession.session_date)).scalars():
        if s.questions:
            n += 1
            if s.session_number != n:
                s.session_number = n
        elif s.session_number:
            s.session_number = 0
    db.flush()


def generate(db: Session, d: date, mode: str | None = None, existing: DailySession | None = None, *,
             exclude_ids: set[int] | None = None, catch_up: dict[int, dict] | None = None) -> DailySession:
    _top_up_templates(db)
    today = clock.today(st.get(db, "timezone"))
    ctx = build_context(db, today, mode, session_date=d, exclude_ids=exclude_ids, catch_up=catch_up)
    sel = build_daily_selection(db, ctx)
    sess = existing or DailySession(session_date=d)
    if existing is None:
        db.add(sess)
    target, lo, hi = budget_bounds(ctx)
    sess.mode = ctx.mode
    sess.status = "generated"
    sess.target_minutes = int(round(target))
    sess.expected_minutes = sel.expected_minutes
    expl = explain(ctx, sel)
    expl["notes"] = sel.notes
    expl["window"] = [lo, hi]
    expl["counts"] = dict(ctx.profile.counts)
    if d != today:
        expl["planned_on"] = today.isoformat()
    sess.explanation = expl
    db.flush()
    for pos, s in enumerate(sel.items, start=1):
        bd = {**s.breakdown, "total": s.score, "bucket": s.bucket, "tier": s.tier, "kind": s.kind,
              "flags": list(s.facts.get("flags") or []), "timed": ctx.profile.timed}
        if s.kind == "retry":
            prev = db.execute(select(Attempt.id).where(Attempt.question_id == s.question.id)
                              .order_by(Attempt.submitted_at.desc()).limit(1)).scalar_one_or_none()
            bd["retry_of_attempt"] = prev
        db.add(SessionQuestion(session_id=sess.id, question_id=s.question.id, subject_code=subject_code(s.question), position=pos,
                               reason=s.reason, score_breakdown=bd))
    db.flush()
    db.refresh(sess)
    renumber(db)
    return sess


def get_or_create_today(db: Session, mode: str | None = None) -> DailySession | None:
    today = clock.today(st.get(db, "timezone"))
    record_missed(db, today)
    sess = get_session(db, today)
    if sess is not None:
        return sess  # never regenerate on refresh
    if not study_day(db, today):
        return None
    return generate(db, today, mode)


def create_extra_today(db: Session, mode: str | None = None) -> DailySession:
    """Weekend/optional session on request."""
    today = clock.today(st.get(db, "timezone"))
    return get_session(db, today) or generate(db, today, mode)


def rebuild(db: Session, sess: DailySession, mode: str, catch_up: dict[int, dict] | None = None) -> DailySession:
    """Explicit user action (e.g. switch to a Light day) — only before anything is answered.
    The session keeps its number."""
    if any(q.status in ANSWERED for q in sess.questions):
        raise ValueError("This session already has answers; it cannot be rebuilt.")
    for q in list(sess.questions):
        db.delete(q)
    db.flush()
    db.refresh(sess)
    return generate(db, sess.session_date, mode, existing=sess, catch_up=catch_up)


# ------------------------------------------------------------ missed sessions ---
def resume_missed(db: Session, sess: DailySession) -> DailySession:
    """Restore a missed day's set: its own questions if it had some, otherwise a set planned with
    today's knowledge that shares nothing with today's set (selection-10)."""
    today = clock.today(st.get(db, "timezone"))
    if sess.questions:
        sess.status = "in_progress" if _answered(sess) else "generated"
        sess.explanation = {**(sess.explanation or {}), "resumed_on": today.isoformat()}
        db.flush()
        renumber(db)
        return sess
    today_sess = get_session(db, today)
    exclude = {q.question_id for q in today_sess.questions} if today_sess and today_sess.id != sess.id else set()
    return generate(db, sess.session_date, None, existing=sess, exclude_ids=exclude)


def skip_missed(db: Session, sess: DailySession) -> None:
    sess.status = "skipped"
    db.flush()


def move_revision_forward(db: Session, sess: DailySession) -> int:
    """'Move important revision forward': the catch-up for this missed day (idempotent)."""
    today = clock.today(st.get(db, "timezone"))
    items = catch_up_candidates(db, today, sess.session_date)
    if sess.status == "missed":
        sess.status = "skipped"
        sess.summary = {"resolution": "catch_up", "items": sorted(items)}
    apply_catch_up(db, today, items)
    db.flush()
    return len(items)


def unfinished(db: Session, today: date) -> list[DailySession]:
    """Earlier sessions that were started but not finished (selection-12)."""
    out = []
    for s in db.execute(select(DailySession).where(DailySession.session_date < today, DailySession.status.in_(ACTIVE),
                                                    DailySession.session_date >= today - timedelta(days=NOTICE_DAYS))
                        .order_by(DailySession.session_date)).scalars():
        if 0 < _answered(s) < len(s.questions):
            out.append(s)
    return out


def close_session(db: Session, sess: DailySession) -> None:
    """Close a partly finished session: the rest is recorded as not attempted (no mastery penalty)."""
    if sess.status == "completed":
        return
    pause_timer(db, sess)
    sess.status = "closed"
    sess.completed_at = utcnow()
    try:
        from app.services.analytics import session_summary

        sess.summary = {**session_summary(db, sess), "closed_early": True}
    except Exception:  # the summary is a convenience; closing must not fail
        sess.summary = {"closed_early": True}
    db.flush()


# -------------------------------------------------------------- timer/drafts ---
def _idle_seconds(db: Session | None = None) -> int:
    minutes = st.get(db, "timer_idle_minutes") if db is not None else None
    return int((minutes or 10) * 60)


def _credit(sess: DailySession, now: datetime) -> int:
    if sess.timer_started_at is None:
        return 0
    since = sess.last_active_at or sess.timer_started_at
    return int(max(0, min((now - since).total_seconds(), HEARTBEAT_CREDIT)))


def time_cap(sess: DailySession) -> int:
    """A session can never record more than max(2 x expected, per-question time + 15 min)."""
    spent = sum(q.time_spent_seconds or 0 for q in sess.questions)
    return int(max(2 * (sess.expected_minutes or 45) * 60, spent + 900))


def elapsed(sess: DailySession) -> int:
    """Active seconds: time between activity signals, never the time the app sat unused."""
    return min(sess.elapsed_seconds + _credit(sess, utcnow()), time_cap(sess))


def start_timer(db: Session, sess: DailySession) -> None:
    if sess.status in ("completed", "closed"):
        return
    now = utcnow()
    if sess.timer_started_at is None:
        sess.timer_started_at = now
        sess.last_active_at = now
    if sess.status == "generated":
        sess.status = "in_progress"
    db.flush()


def touch(db: Session, sess: DailySession) -> None:
    """Any activity (page view, heartbeat, draft save, answer) counts as active time."""
    if sess.status in ("completed", "closed"):
        return
    now = utcnow()
    if sess.timer_started_at is None:
        start_timer(db, sess)
        return
    since = sess.last_active_at or sess.timer_started_at
    gap = (now - since).total_seconds()
    sess.elapsed_seconds = min(sess.elapsed_seconds + _credit(sess, now), time_cap(sess))
    if gap > _idle_seconds(db):
        sess.pause_note = f"The timer stopped counting after {_idle_seconds(db) // 60} minutes without activity; that time was not recorded."
    sess.last_active_at = now
    db.flush()


def heartbeat(db: Session, sess: DailySession) -> dict:
    touch(db, sess)
    return {"elapsed": elapsed(sess), "running": sess.timer_started_at is not None, "note": sess.pause_note}


def pause_timer(db: Session, sess: DailySession, reason: str | None = None) -> None:
    if sess.timer_started_at is not None:
        sess.elapsed_seconds = elapsed(sess)
        sess.timer_started_at = None
        sess.last_active_at = None
        notes = {
            "idle": f"Paused automatically after {_idle_seconds(db) // 60} minutes without activity.",
            "hidden": "Paused while the app was in the background.",
            "day_end": "Paused at the end of the day.",
        }
        sess.pause_note = notes.get(reason or "")
    db.flush()


def save_draft(db: Session, sq: SessionQuestion, text: str, time_spent: int | None = None) -> None:
    sq.draft_text = text
    sq.draft_saved_at = utcnow()
    if sq.status == "pending":
        sq.status = "draft"
    if time_spent is not None:
        sq.time_spent_seconds = max(sq.time_spent_seconds, int(time_spent))
    if sq.session is not None:
        touch(db, sq.session)
    db.flush()


def progress(sess: DailySession) -> dict:
    done = {"MATHS": 0, "ENGLISH": 0, "LEGAL": 0}
    total = {"MATHS": 0, "ENGLISH": 0, "LEGAL": 0}
    remaining = 0.0
    for sq in sess.questions:
        total[sq.subject_code] = total.get(sq.subject_code, 0) + 1
        if sq.status in ANSWERED:
            done[sq.subject_code] = done.get(sq.subject_code, 0) + 1
        else:
            remaining += sq.question.estimated_minutes
    n_done, n_total = sum(done.values()), sum(total.values())
    return {"done": done, "total": total, "n_done": n_done, "n_total": n_total,
            "pct": round(100 * n_done / n_total) if n_total else 0, "remaining_minutes": round(remaining)}


def maybe_complete(db: Session, sess: DailySession) -> bool:
    if sess.status == "completed":
        return True
    if sess.questions and all(q.status in ANSWERED for q in sess.questions):
        pause_timer(db, sess)
        sess.status = "completed"
        sess.completed_at = utcnow()
        from app.services.analytics import session_summary

        sess.summary = session_summary(db, sess)
        db.flush()
        return True
    return False


def first_attempts(db: Session, sess: DailySession) -> dict[int, Attempt]:
    ids = [q.id for q in sess.questions]
    out: dict[int, Attempt] = {}
    if not ids:
        return out
    for a in db.execute(select(Attempt).where(Attempt.session_question_id.in_(ids)).order_by(Attempt.attempt_number)).scalars():
        out.setdefault(a.session_question_id, a)
    return out


def counts_for_streak(db: Session, sess: DailySession) -> bool:
    """A study day counts at >= 80% of its questions answered or >= 60 active minutes."""
    if sess.status == "completed":
        return True
    if not sess.questions:
        return False
    frac = _answered(sess) / len(sess.questions)
    minutes = sess.elapsed_seconds / 60
    return frac >= float(st.get(db, "streak_min_fraction") or 0.8) or minutes >= float(st.get(db, "streak_min_minutes") or 60)


def weekday_streak(db: Session, today: date) -> int:
    weekdays = st.get(db, "weekdays") or [0, 1, 2, 3, 4]
    counted = {s.session_date for s in db.execute(select(DailySession).where(DailySession.session_date <= today)).scalars()
               if counts_for_streak(db, s)}
    streak, d = 0, today
    if d not in counted:
        d -= timedelta(days=1)
    while True:
        if d.weekday() in weekdays:
            if d in counted:
                streak += 1
            else:
                break
        d -= timedelta(days=1)
        if streak > 400:
            break
    return streak


def history(db: Session, limit: int = 120) -> list[dict]:
    """Session history rows for the sessions page (selection-12)."""
    out = []
    for s in db.execute(select(DailySession).order_by(DailySession.session_date.desc()).limit(limit)).scalars():
        p = progress(s) if s.questions else None
        out.append({"s": s, "p": p, "minutes": round(elapsed(s) / 60) if s.questions else 0})
    return out


def exposure_for(db: Session, qid: int) -> QuestionExposure | None:
    return db.execute(select(QuestionExposure).where(QuestionExposure.question_id == qid)).scalar_one_or_none()


def now_local() -> datetime:
    return datetime.now()


# ------------------------------------------------------- real-time swap (v2-swap) ---
class SwapRefused(ValueError):
    """The question cannot be swapped (already answered, session finished, ...)."""


def swap_question(db: Session, sess: DailySession, sq: SessionQuestion, reason: str, lock: bool = False,
                  actor: str = "student"):
    """Swap an unanswered question (or a whole English reading set) for the engine's best
    replacement of a similar length, or remove it from the session when nothing suitable exists.

    The swapped-out question records no attempt, no skip and no exposure (it simply leaves the
    session); the swap itself is logged in ``session_swaps``. With reason "not_learnt" and
    ``lock``, the question's plan item becomes LOCKED (Not taught yet) first, so this and future
    sessions avoid it until the student unlocks it. Returns the ``SessionSwap`` record."""
    from app.models import LearningPlanItem, SessionSwap
    from app.models.common import LOCKED
    from app.selection import swap as sw
    from app.selection.engine import stimulus_minutes
    from app.services import plan as plan_service

    if reason not in sw.REASONS:
        raise SwapRefused("Choose why you want to swap this question.")
    if sq.session_id != sess.id:
        raise SwapRefused("That question is not part of this session.")
    today = clock.today(st.get(db, "timezone"))
    unit = sw.unit_for(sess, sq)
    why = sw.blocked_reason(db, unit)
    if why:
        raise SwapRefused(why)
    code = unit.code
    orig_qs = unit.questions
    orig_item = db.get(LearningPlanItem, orig_qs[0].plan_item_id) if orig_qs[0].plan_item_id else None
    old_positions = unit.positions
    label = unit.label()
    minutes_before = float(sess.expected_minutes or 0)
    from_text = [(q.question_text or "")[:140] for q in orig_qs]
    from_title = orig_qs[0].stimulus.title if unit.passage and orig_qs[0].stimulus else None
    from_form = unit.form  # read before the rows change

    locked = None
    offer = sw.lock_offer(unit)
    if reason == "not_learnt" and lock and offer:
        locked = plan_service.set_status(db, offer["item_id"], LOCKED)  # explicit choice: never silent
    if code == "MATHS":
        _top_up_templates(db)
    rep = sw.find_replacement(db, unit, reason, today)

    rec = SessionSwap(session_id=sess.id, actor=actor, reason=reason, subject_code=code, position=old_positions[0],
                      from_question_ids=[q.id for q in orig_qs], to_question_ids=[s.question.id for s in rep.items],
                      plan_item_id=orig_item.id if orig_item else None, locked_plan_item_id=locked.id if locked else None,
                      outcome="replaced" if rep.items else "removed", message="")
    db.add(rec)
    db.flush()

    if rep.items:
        rows = list(unit.sqs)
        for row, s in zip(rows, rep.items):
            old_qid = row.question_id
            row.question_id = s.question.id
            row.question = s.question
            row.status = "pending"
            row.draft_text = None
            row.draft_saved_at = None
            row.time_spent_seconds = 0
            row.reason = f"Swapped in ({sw.REASON_TEXT[reason]}). {s.reason}"
            row.score_breakdown = {**s.breakdown, "total": s.score, "bucket": s.bucket, "tier": s.tier, "kind": s.kind,
                                   "flags": list(s.facts.get("flags") or []), "timed": rep.ctx.profile.timed if rep.ctx else False,
                                   "swap": {"id": rec.id, "reason": reason, "replaced": old_qid}}
        for row in rows[len(rep.items):]:  # fewer questions than before (never more)
            db.delete(row)
    else:
        for row in unit.sqs:
            db.delete(row)
    db.flush()
    db.refresh(sess)
    for k, row in enumerate(sorted(sess.questions, key=lambda x: x.position), start=1):
        if row.position != k:
            row.position = k
    db.flush()
    db.refresh(sess)

    qs = [x.question for x in sess.questions]
    sess.expected_minutes = round(sum(float(q.estimated_minutes or 0) for q in qs) + stimulus_minutes(qs), 1)
    if rep.ctx is not None:
        sess.explanation = sw.refreshed_explanation(rep.ctx, sess, code)

    # what the student is told (and what "Why these questions?" lists)
    new_rows = [x for x in sess.questions if (x.score_breakdown or {}).get("swap", {}).get("id") == rec.id]
    why_txt = {"not_learnt": "you have not learnt it yet", "different": "you asked for a different one"}[reason]
    if unit.passage and reason == "not_learnt":
        why_txt = "you have not studied this kind of text" + (f" ({from_form.lower()})" if from_form else "") + " yet"
    if unit.passage:
        what = f"the passage '{from_title}' ({label})" if from_title else f"the passage ({label})"
    else:
        what = f"{label} ({sw.item_name(orig_item)})"
    if new_rows:
        new_qs = [x.question for x in new_rows]
        mins = round(sum(float(q.estimated_minutes or 0) for q in new_qs) + (stimulus_minutes(new_qs) if unit.passage else 0))
        if unit.passage:
            stim = new_qs[0].stimulus
            marks = " and ".join(str(q.marks) for q in new_qs)
            into = (f"'{stim.title}'" + (f" ({stim.form.lower()})" if stim and stim.form else "") if stim else "another passage")
            msg = f"Swapped {what} because {why_txt}: now {into} with {marks}-mark questions, about {mins} minutes including reading."
        else:
            q = new_qs[0]
            item = db.get(LearningPlanItem, q.plan_item_id) if q.plan_item_id else None
            msg = (f"Swapped {what} because {why_txt}: Q{new_rows[0].position} is now a {q.marks}-mark question on "
                   f"{sw.item_name(item)}, about {mins} minutes.")
        if rep.relaxed:
            msg += " Nothing closer in length was available."
    else:
        msg = (f"Removed {what} from today's session because {why_txt}, and no suitable replacement exists: {rep.why_none}. "
               f"Today's set is now about {round(sess.expected_minutes)} minutes.")
    msg += " Nothing was recorded for the question you swapped out."
    if locked is not None:
        msg += (f" {sw.item_name(locked)} is now marked Not taught yet, so sessions leave it out until you change it on "
                "the Learning plan.")
    if reason == "not_learnt" and orig_item is not None and not unit.passage:
        same = [x.position for x in sess.questions if x.question.plan_item_id == orig_item.id and x.status not in ANSWERED]
        if same:
            qn = " and ".join(f"Q{p}" for p in same)
            msg += f" {qn} {'is' if len(same) == 1 else 'are'} also on {sw.item_name(orig_item)}: swap {'it' if len(same) == 1 else 'them'} too if you have not learnt it."
    rec.message = msg
    rec.to_question_ids = [x.question_id for x in new_rows]
    rec.details = {
        "local_time": clock.local_now().strftime("%H:%M"), "from_positions": old_positions,
        "to_positions": [x.position for x in new_rows], "from_text": from_text, "from_title": from_title, "from_form": from_form,
        "relaxed": rep.relaxed, "why_none": rep.why_none, "minutes_before": minutes_before,
        "minutes_after": sess.expected_minutes, "facts": rep.facts,
    }
    if not sess.questions:
        renumber(db)
    else:
        maybe_complete(db, sess)
    db.flush()
    return rec


def swaps_for(db: Session, sess: DailySession) -> list:
    from app.models import SessionSwap

    return list(db.execute(select(SessionSwap).where(SessionSwap.session_id == sess.id).order_by(SessionSwap.created_at, SessionSwap.id)).scalars())


def swap_controls(db: Session, sess: DailySession) -> dict[int, dict]:
    """For each session row: can it be swapped, and what the control should offer."""
    from app.selection import swap as sw

    if sess.status in sw.FINISHED or not sess.questions:
        return {}
    ids = [x.id for x in sess.questions]
    attempted = sw._attempted(db, ids)
    photos = sw._pending_photos(db, ids)
    out: dict[int, dict] = {}
    for sq in sess.questions:
        unit = sw.unit_for(sess, sq)
        why = sw.blocked_reason(db, unit, attempted=attempted, photos=photos)
        out[sq.id] = {
            "can": why is None, "why_not": why, "is_set": unit.passage, "positions": unit.positions, "label": unit.label(),
            "lead": unit.sqs[0].id == sq.id, "minutes": round(unit.minutes), "marks": unit.marks,
            "form": (unit.form or "").lower() or None, "lock": sw.lock_offer(unit) if why is None else None,
            "draft": any(x.status == "draft" for x in unit.sqs),
        }
    return out
